// Suscripción dinámica: el prefijo sale de la variable de entorno TOPIC_BASE (no queda en el flujo)
const base = env.get('TOPIC_BASE');
if (!base || !env.get('DEVICE_KEYS')) { node.error('Defina TOPIC_BASE y DEVICE_KEYS como variables de entorno antes de iniciar Node-RED'); node.status({ fill: 'red', shape: 'ring', text: 'faltan variables de entorno' }); return null; }
node.status({ fill: 'green', shape: 'dot', text: base });
return { action: 'subscribe', topic: [ { topic: base + '/+/telemetry', qos: 0 }, { topic: base + '/+/audit', qos: 1 } ] };

// ===== utilidades comunes (mismo protocolo que server/src/protocol.js) =====
function keys() {
  const m = {};
  String(env.get('DEVICE_KEYS') || '').split(',').forEach(p => { const i = p.indexOf(':'); if (i > 0) m[p.slice(0, i).trim()] = p.slice(i + 1).trim(); });
  return m;
}
const hmac = (k, t) => crypto.createHmac('sha256', Buffer.from(k, 'utf8')).update(t, 'utf8').digest('hex');
function safeEq(a, b) {
  if (typeof a !== 'string' || !/^[0-9a-f]{64}$/i.test(a) || !/^[0-9a-f]{64}$/i.test(b)) return false;
  return crypto.timingSafeEqual(Buffer.from(a.toLowerCase(), 'hex'), Buffer.from(b.toLowerCase(), 'hex'));
}
const nowS = () => Math.floor(Date.now() / 1000);

// ===== Seguridad de entrada: tamaño, JSON, lista blanca, esquema, HMAC, anti-repetición, abuso, rangos =====
const WINDOW = 30, RATE_MAX = 12, RATE_WIN = 10000, BLOCK_MS = 60000, BAD_MAX = 5, SEQ_WINDOW = 32;
const parts = msg.topic.split('/');
const kind = parts.pop();
const deviceId = parts.pop();
const raw = typeof msg.payload === 'string' ? msg.payload : String(msg.payload);
// Limitador: máx. 3 eventos iguales cada 10 s para que un flood no inunde la auditoría
const audit = (nivel, codigo, detalle) => {
  const th = flow.get('auditTh') || {}; const k = codigo + ':' + deviceId; const now = Date.now();
  if (!th[k] || now - th[k].t > 10000) th[k] = { t: now, n: 0 };
  th[k].n++; flow.set('auditTh', th);
  if (th[k].n > 3) return;
  node.send([null, { payload: { fecha: new Date().toISOString(), origen: 'node-red', nivel, codigo, deviceId, detalle } }]);
};
const reject = (codigo, detalle, alerta) => { audit(alerta ? 'alerta' : 'warn', codigo, detalle); node.status({ fill: 'red', shape: 'ring', text: codigo }); return null; };

if (kind !== 'telemetry' && kind !== 'audit') return null;
if (raw.length > 512) return reject('PAYLOAD_GRANDE', raw.length + ' bytes');
let m; try { m = JSON.parse(raw); } catch (e) { return reject('JSON_INVALIDO', 'no se pudo parsear'); }
if (!m || typeof m !== 'object' || Array.isArray(m)) return reject('JSON_INVALIDO', 'no es objeto');
const key = keys()[deviceId];
if (!key) return reject('DISPOSITIVO_DESCONOCIDO', deviceId);
if (m.deviceId !== deviceId) return reject('DEVICE_MISMATCH', 'tópico=' + deviceId + ' msg=' + m.deviceId);

const blocked = flow.get('blocked') || {};
if (blocked[deviceId] && blocked[deviceId] > Date.now()) return reject('BLOQUEADO', 'bloqueado por abuso');

if (typeof m.boot !== 'string' || !/^[0-9a-f]{8}$/i.test(m.boot) || !Number.isInteger(m.seq) || m.seq < 0 || !Number.isInteger(m.ts) || typeof m.sig !== 'string') return reject('ESQUEMA', 'campos base inválidos');
let canon;
if (kind === 'telemetry') {
  if (typeof m.temp !== 'number' || !isFinite(m.temp) || typeof m.hum !== 'number' || !isFinite(m.hum) || typeof m.led !== 'boolean') return reject('ESQUEMA', 'temp/hum/led inválidos');
  canon = ['T', m.deviceId, m.boot, m.seq, m.ts, m.temp.toFixed(1), m.hum.toFixed(1), m.led ? 1 : 0].join('|');
} else {
  for (const f of ['event', 'ref', 'detail']) if (typeof m[f] !== 'string' || m[f].length > 64 || m[f].includes('|')) return reject('ESQUEMA', f + ' inválido');
  canon = ['A', m.deviceId, m.boot, m.seq, m.ts, m.event, m.ref, m.detail].join('|');
}

// HMAC
if (!safeEq(m.sig, hmac(key, canon))) {
  const bad = (flow.get('badSig') || []).filter(t => Date.now() - t < 60000); bad.push(Date.now()); flow.set('badSig', bad);
  if (bad.length >= BAD_MAX) return reject('ATAQUE_FIRMAS', bad.length + ' firmas inválidas en 60 s', true);
  return reject('HMAC_INVALIDO', 'la firma no coincide');
}
// Abuso de un emisor autenticado
const rate = (flow.get('rate') || []).filter(t => Date.now() - t < RATE_WIN); rate.push(Date.now()); flow.set('rate', rate);
if (rate.length > RATE_MAX) { blocked[deviceId] = Date.now() + BLOCK_MS; flow.set('blocked', blocked); return reject('ABUSO_RATE', rate.length + ' msgs en 10 s -> bloqueado 60 s', true); }
// Anti-repetición
const skew = Math.abs(nowS() - m.ts);
if (skew > WINDOW) return reject('REPLAY_TS', 'ts fuera de ventana (' + skew + ' s)');
const seen = flow.get('seen') || {};
const mid = deviceId + ':' + m.boot + ':' + m.seq;
for (const k in seen) if (seen[k] < Date.now()) delete seen[k];
if (seen[mid]) return reject('REPLAY_DUPLICADO', m.boot + '-' + m.seq + ' ya recibido', true);
const last = (flow.get('lastSeq') || {})[deviceId];
if (last && last.boot === m.boot && m.seq <= last.seq - SEQ_WINDOW) return reject('REPLAY_SEQ', 'seq demasiado antiguo', true);
// Rangos físicos y anomalías
if (kind === 'telemetry') {
  if (m.temp < -40 || m.temp > 80) return reject('FUERA_DE_RANGO', 'temp=' + m.temp);
  if (m.hum < 0 || m.hum > 100) return reject('FUERA_DE_RANGO', 'hum=' + m.hum);
  const prev = flow.get('lastTemp');
  if (prev !== undefined && Math.abs(m.temp - prev) > 10) audit('alerta', 'ANOMALIA', 'salto ' + prev + ' -> ' + m.temp);
  flow.set('lastTemp', m.temp);
}
// Aceptado
seen[mid] = Date.now() + 2 * WINDOW * 1000; flow.set('seen', seen);
const ls = flow.get('lastSeq') || {}; if (!last || last.boot !== m.boot || m.seq > last.seq) { ls[deviceId] = { boot: m.boot, seq: m.seq }; flow.set('lastSeq', ls); }
flow.set('lastSeen', Date.now());
node.status({ fill: 'green', shape: 'dot', text: kind + ' OK seq ' + m.seq });
if (kind === 'telemetry') { flow.set('led', m.led); return [{ payload: m }, null]; }
const nivel = (m.event === 'CMD_OK' || m.event === 'ARRANQUE' || m.event === 'RECONEXION') ? 'info' : 'alerta';
return [null, { payload: { fecha: new Date().toISOString(), origen: 'dispositivo', nivel, codigo: m.event, deviceId, detalle: (m.ref ? 'ref=' + m.ref + ' ' : '') + m.detail } }];

// Reparte la telemetría validada a los widgets
const m = msg.payload;
const fecha = new Date(m.ts * 1000).toLocaleString();
return [
  { payload: m.temp },
  { payload: m.hum },
  [ { topic: 'Temperatura (°C)', payload: m.temp }, { topic: 'Humedad (%)', payload: m.hum } ],
  { payload: m.led ? '🟢 Encendido' : '⚫ Apagado' },
  { payload: fecha + ' · seq ' + m.seq + ' · HMAC ✔' }
];

// Acumula los últimos 50 eventos de auditoría para la tabla
const list = flow.get('auditList') || [];
list.unshift(msg.payload);
if (list.length > 50) list.length = 50;
flow.set('auditList', list);
return { payload: list };

// Estado del dispositivo: en línea si hubo un mensaje válido en los últimos 20 s
const last = flow.get('lastSeen');
const online = last && Date.now() - last < 20000;
const blocked = Object.values(flow.get('blocked') || {}).some(t => t > Date.now());
return { payload: (online ? '🟢 En línea' : '🔴 Fuera de línea') + (blocked ? ' · ⛔ bloqueado por abuso' : '') };

// ===== utilidades comunes (mismo protocolo que server/src/protocol.js) =====
function keys() {
  const m = {};
  String(env.get('DEVICE_KEYS') || '').split(',').forEach(p => { const i = p.indexOf(':'); if (i > 0) m[p.slice(0, i).trim()] = p.slice(i + 1).trim(); });
  return m;
}
const hmac = (k, t) => crypto.createHmac('sha256', Buffer.from(k, 'utf8')).update(t, 'utf8').digest('hex');
function safeEq(a, b) {
  if (typeof a !== 'string' || !/^[0-9a-f]{64}$/i.test(a) || !/^[0-9a-f]{64}$/i.test(b)) return false;
  return crypto.timingSafeEqual(Buffer.from(a.toLowerCase(), 'hex'), Buffer.from(b.toLowerCase(), 'hex'));
}
const nowS = () => Math.floor(Date.now() / 1000);

// ===== Firma de comandos LED (servidor -> ESP32) con límite de tasa =====
const value = msg.payload;
const deviceId = env.get('DEVICE_ID') || Object.keys(keys())[0];
const key = keys()[deviceId];
const audit = (nivel, codigo, detalle) => ({ payload: { fecha: new Date().toISOString(), origen: 'dashboard', nivel, codigo, deviceId, detalle } });
if (!key) return [null, audit('alerta', 'SIN_CLAVE', 'DEVICE_KEYS no configurado')];
if (value !== 'on' && value !== 'off') return [null, audit('warn', 'CMD_INVALIDO', String(value))];
const times = (flow.get('cmdTimes') || []).filter(t => Date.now() - t < 60000);
if (times.length >= 20) return [null, audit('alerta', 'ABUSO_COMANDOS', '> 20 comandos/min')];
times.push(Date.now()); flow.set('cmdTimes', times);
const c = { deviceId, cmdId: crypto.randomBytes(8).toString('hex'), ts: nowS(), action: 'led', value };
c.sig = hmac(key, ['C', c.deviceId, c.cmdId, c.ts, c.action, c.value].join('|'));
return [{ topic: env.get('TOPIC_BASE') + '/' + deviceId + '/cmd', payload: JSON.stringify(c), qos: 1 }, audit('info', 'CMD_ENVIADO', 'led=' + value + ' cmd=' + c.cmdId)];
